/**
 * Sleepy Cat palette system — Cream / Sage / Lavender / Newspaper.
 *
 * Each palette is a set of CSS custom properties on <html data-palette="...">.
 * Cream is the v0.8.0 default. Existing themes (light/dark/sepia) still work
 * via theme.ts; the palette is layered on top via data-palette.
 *
 * Time complexity: every helper is O(1).
 */

export type PaletteId = 'cream' | 'sage' | 'lavender' | 'newspaper';

const KEY = 'bilko_etch_palette_v1';
const DEFAULT: PaletteId = 'cream';

export const PALETTES: ReadonlyArray<{ id: PaletteId; label: string; sub: string }> = [
  { id: 'cream',     label: 'Cream',     sub: 'Kitchen cream' },
  { id: 'sage',      label: 'Sage',      sub: 'Garden sage' },
  { id: 'lavender',  label: 'Lavender',  sub: 'Yarn lavender' },
  { id: 'newspaper', label: 'Newspaper', sub: 'Newspaper ink' },
];

function isPaletteId(v: string | null): v is PaletteId {
  return v === 'cream' || v === 'sage' || v === 'lavender' || v === 'newspaper';
}

export function getPalette(): PaletteId {
  try {
    const v = localStorage.getItem(KEY);
    return isPaletteId(v) ? v : DEFAULT;
  } catch { return DEFAULT; }
}

export function setPalette(p: PaletteId): void {
  document.documentElement.dataset['palette'] = p;
  try { localStorage.setItem(KEY, p); } catch {}
}

/** Boot-time application of the persisted palette (or default). */
export function applyPalette(): void {
  document.documentElement.dataset['palette'] = getPalette();
}

// Square-size tweak — applied as a CSS var. Mobile-aware default (44 under 480
// wide, 56 elsewhere). Range 44–84 per the design brief.
const SIZE_KEY = 'bilko_etch_cellsize_v1';

export function getCellSize(): number {
  try {
    const v = localStorage.getItem(SIZE_KEY);
    if (v) {
      const n = Number(v);
      if (n >= 36 && n <= 96) return n;
    }
  } catch {}
  // Mobile-friendly default: 44 below 480px, 56 elsewhere.
  try {
    if (typeof window !== 'undefined' && window.innerWidth < 480) return 44;
  } catch {}
  return 56;
}

export function setCellSize(px: number): void {
  const n = Math.max(36, Math.min(96, Math.round(px)));
  document.documentElement.style.setProperty('--etch-cell-size', `${n}px`);
  try { localStorage.setItem(SIZE_KEY, String(n)); } catch {}
}

export function applyCellSize(): void {
  document.documentElement.style.setProperty('--etch-cell-size', `${getCellSize()}px`);
}

// Auto-fade finished clues toggle (default ON).
const FADE_KEY = 'bilko_etch_autofade_v1';

export function getAutoFade(): boolean {
  try {
    const v = localStorage.getItem(FADE_KEY);
    if (v === '0') return false;
  } catch {}
  return true;
}

export function setAutoFade(on: boolean): void {
  if (on) {
    delete document.documentElement.dataset['autofade'];
    try { localStorage.removeItem(FADE_KEY); } catch {}
  } else {
    document.documentElement.dataset['autofade'] = 'off';
    try { localStorage.setItem(FADE_KEY, '0'); } catch {}
  }
}

export function applyAutoFade(): void {
  if (!getAutoFade()) document.documentElement.dataset['autofade'] = 'off';
}
