import { useEffect, useMemo, useRef } from 'react';

/**
 * Palette-aware confetti rain. 60 soft dots fall from the top of the viewport
 * with random drift + spin. Colors are pulled from the active palette (the
 * --sc-accent / --sc-accent2 / --sc-mark / --sc-ink CSS vars) so each palette
 * gets its own celebration palette without any prop wiring.
 *
 * Respects prefers-reduced-motion: renders nothing if the user prefers reduced
 * (the animation rule in CSS also disables it as a belt-and-braces).
 *
 * Time complexity: O(N) for N=60 particles, one-shot.
 */
interface Dot {
  x: number;
  size: number;
  hue: string;
  delay: number;
  duration: number;
  spin: number;
  drift: number;
}

export function SleepyCatConfetti({ active, onDone }: { active: boolean; onDone: () => void }) {
  const startedRef = useRef(false);

  const dots = useMemo<Dot[]>(() => {
    if (!active) return [];
    // Read live palette colors. color-mix can't be parsed in JS so we just use
    // the raw tokens; CSS resolves them to actual colors when rendering the dot.
    const colors = [
      'var(--sc-accent)',
      'var(--sc-accent2)',
      'var(--sc-mark)',
      'var(--sc-ink)',
      'var(--sc-line)',
    ];
    const arr: Dot[] = [];
    for (let i = 0; i < 60; i++) {
      arr.push({
        x: 50 + (Math.random() - 0.5) * 80,
        size: 8 + Math.random() * 8,
        hue: colors[Math.floor(Math.random() * colors.length)]!,
        delay: Math.random() * 0.6,
        duration: 1.8 + Math.random() * 1.4,
        spin: Math.random() * 720 - 360,
        drift: (Math.random() - 0.5) * 100,
      });
    }
    return arr;
  }, [active]);

  useEffect(() => {
    if (!active || startedRef.current) return;
    startedRef.current = true;
    const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
    const t = setTimeout(onDone, reduced ? 200 : 3400);
    return () => clearTimeout(t);
  }, [active, onDone]);

  if (!active || dots.length === 0) return null;

  return (
    <div className="sc-confetti-layer" aria-hidden="true" data-testid="sc-confetti">
      {dots.map((d, i) => (
        <span
          key={i}
          className="sc-confetti-dot"
          style={{
            left: `${d.x}%`,
            width: d.size,
            height: d.size,
            background: d.hue,
            animationDelay: `${d.delay}s`,
            animationDuration: `${d.duration}s`,
            ['--drift' as any]: `${d.drift}px`,
            ['--spin' as any]: `${d.spin}deg`,
          } as React.CSSProperties}
        />
      ))}
    </div>
  );
}
