import { useEffect, useState } from 'react';
import { PALETTES, getPalette, setPalette, getCellSize, setCellSize, getAutoFade, setAutoFade, type PaletteId } from './palette';

/**
 * Floating tweaks panel — palette switcher, square-size slider, auto-fade
 * toggle. The panel is a small FAB at the bottom-right that expands to the
 * settings card. Lives entirely in localStorage; no store coupling.
 */
export function SleepyCatTweaks() {
  const [open, setOpen] = useState(false);
  const [palette, setPaletteState] = useState<PaletteId>(getPalette());
  const [size, setSizeState] = useState<number>(getCellSize());
  const [fade, setFade] = useState<boolean>(getAutoFade());

  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === 'Escape' && open) setOpen(false);
    }
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open]);

  function onPaletteChange(p: PaletteId) {
    setPaletteState(p);
    setPalette(p);
  }
  function onSizeChange(v: number) {
    setSizeState(v);
    setCellSize(v);
  }
  function onFadeChange(v: boolean) {
    setFade(v);
    setAutoFade(v);
  }

  return (
    <>
      <button
        type="button"
        className="sc-tweaks-fab"
        onClick={() => setOpen((o) => !o)}
        aria-label="Comfort settings"
        aria-expanded={open}
        data-testid="sc-tweaks-fab"
      >
        ✦
      </button>
      {open && (
        <div role="dialog" className="sc-tweaks-panel" aria-label="Comfort settings">
          <h3>Comfort</h3>
          <div className="sc-tweaks-section">
            <h4>Palette</h4>
            <div className="sc-tweaks-radio-row">
              {PALETTES.map((p) => (
                <label key={p.id} className="sc-tweaks-radio">
                  <input
                    type="radio"
                    name="sc-palette"
                    value={p.id}
                    checked={palette === p.id}
                    onChange={() => onPaletteChange(p.id)}
                  />
                  <span>
                    {p.label}{' '}
                    <span style={{ opacity: 0.55, fontSize: 13 }}>· {p.sub}</span>
                  </span>
                </label>
              ))}
            </div>
          </div>
          <div className="sc-tweaks-section">
            <h4>Square size</h4>
            <label className="sc-tweaks-slider">
              <input
                type="range"
                min={44}
                max={84}
                step={2}
                value={size}
                onChange={(e) => onSizeChange(Number(e.target.value))}
                aria-label="Square size in pixels"
                data-testid="sc-size-slider"
              />
              <span style={{ minWidth: 48, textAlign: 'right' }}>{size}px</span>
            </label>
          </div>
          <div className="sc-tweaks-section">
            <h4>Helpers</h4>
            <label className="sc-tweaks-toggle">
              <input
                type="checkbox"
                checked={fade}
                onChange={(e) => onFadeChange(e.target.checked)}
              />
              Fade finished rows &amp; columns
            </label>
          </div>
        </div>
      )}
    </>
  );
}
