import { useGameState } from '../../state/store';

/**
 * Sleepy Cat date strip + puzzle title. Sits between the top bar and the
 * paper card. Reads the current mode/size to pick a friendly title.
 *
 * Time complexity: O(1).
 */

const SIZE_LABELS: Record<string, string> = {
  sketch: 'Tiny', beginner: 'Small', intermediate: 'Medium', tall: 'Tall', expert: 'Big',
};

function todayLabel(): string {
  const d = new Date();
  return d.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
}

export function SleepyCatHeader() {
  const { mode, size, board } = useGameState();
  if (board.cells.length === 0) return null;
  const isDaily = mode === 'daily';
  const kicker = isDaily
    ? `TODAY'S SKETCH · ${todayLabel()}`
    : `FREE PLAY · ${SIZE_LABELS[size] ?? size}`;
  const title = isDaily ? 'A sleepy cat' : `A ${SIZE_LABELS[size]?.toLowerCase() ?? size} sketch`;
  return (
    <div className="sc-date-strip" data-testid="sc-date-strip">
      <div className="sc-kicker">{kicker}</div>
      <h2 className="sc-title">{title}</h2>
    </div>
  );
}
