import { mark, freezeBoard } from './board';
import type { Board, Coord, CellMarkInput, Mark } from './types';

/**
 * Apply the same mark across an ordered path of coords (player drag gesture).
 * No-ops on already-matching cells. Returns one new board with all changes applied.
 */
export function dragMark(b: Board, path: Coord[], kind: CellMarkInput): Board {
  let out = b;
  for (const c of path) out = mark(out, c, kind);
  return out;
}

/**
 * Set-semantics drag: first cell determines paint vs. erase for the whole gesture.
 * O(path.length); path.length is bounded by rows*cols ≤ 100.
 *
 * Paint mode (first cell doesn't match kind): every cell becomes `kind`,
 * overwriting any prior mark. Cells already at target are skipped (idempotent).
 *
 * Erase mode (first cell matches kind, or kind === 'clear'): cells that
 * currently carry `kind` become 'unmarked'; others are untouched.
 */
export function dragSet(b: Board, path: Coord[], kind: CellMarkInput): Board {
  if (path.length === 0) return b;
  const first = path[0]!;
  const fIdx = first.row * b.cols + first.col;
  const cur = b.cells[fIdx];
  const erasing = kind === 'clear'
    || (kind === 'fill' && cur === 'fill')
    || (kind === 'cross' && cur === 'cross');
  const target: Mark = erasing ? 'unmarked' : kind as Mark;
  const cells = b.cells.slice() as Mark[];
  let changed = false;
  for (const c of path) {
    const idx = c.row * b.cols + c.col;
    if (idx < 0 || idx >= cells.length) continue;
    if (erasing && cells[idx] !== kind) continue;
    if (!erasing && cells[idx] === target) continue;
    cells[idx] = target;
    changed = true;
  }
  if (!changed) return b;
  return freezeBoard({ ...b, cells });
}
