import { useStore } from '../../state/store';
import { bus } from '../../lib/bus';

/**
 * Unified v0.8.0 hint — places one correct cell, increments hint count,
 * pulses the cell. Single source of truth for the H key, toolbar button,
 * and the nudge free-hint flow.
 * Time complexity: O(cells) — bounded by board size.
 */
export function placeOneHint(): void {
  const s = useStore.getState();
  if (s.solved || s.revealed || s.paused) return;
  const board = s.board;
  const fills: number[] = [];
  const bad: number[] = [];
  for (let i = 0; i < board.solution.length; i++) {
    const need = board.solution[i] === 1;
    const have = board.cells[i] === 'fill';
    if (need && !have) fills.push(i);
    else if (!need && have) bad.push(i);
  }
  const pick = fills.length
    ? fills[Math.floor(Math.random() * fills.length)]!
    : bad.length ? bad[Math.floor(Math.random() * bad.length)]! : -1;
  if (pick < 0) return;
  const row = Math.floor(pick / board.cols);
  const col = pick % board.cols;
  const needFill = board.solution[pick] === 1;
  s.actions.applyMark({ row, col }, needFill ? 'fill' : 'clear');
  s.actions.noteHintUsed();
  bus.emit('hintApplied', { row, col, cols: board.cols });
}
