import { useEffect, useState } from 'react';
import { SleepyCatConfetti } from './SleepyCatConfetti';
import { bus } from '../../lib/bus';

/**
 * Wires the SleepyCat win celebration: confetti rain + cat color reveal
 * (`data-revealed="1"` on .etch-board so cells animate via CSS).
 *
 * Always fires on win (not just personal best) — the design brief says every
 * puzzle finish gets a celebration. Reduced motion: confetti is a no-op,
 * reveal still toggles the attribute but the CSS animation is disabled.
 */
export function SleepyCatWin() {
  const [active, setActive] = useState(false);

  useEffect(() => {
    const off = bus.on('puzzleSolved', () => {
      // Add the data-revealed attr so the board animates cells.
      const board = document.querySelector<HTMLElement>('.etch-board');
      if (board) {
        board.setAttribute('data-revealed', '1');
      }
      setActive(true);
    });
    const offNew = bus.on('newGame', () => {
      // Reset confetti + reveal so next puzzle starts clean.
      const board = document.querySelector<HTMLElement>('.etch-board');
      if (board) board.removeAttribute('data-revealed');
      setActive(false);
    });
    return () => { off(); offNew(); };
  }, []);

  return <SleepyCatConfetti active={active} onDone={() => setActive(false)} />;
}
