import { useCallback, useEffect, useRef, useState } from 'react';
import { useStore, useGameActions, useGameState } from '../../state/store';
import { bus } from '../../lib/bus';
import { placeOneHint } from './hint';

/**
 * Sleepy Cat toolbar — segmented Fill / Mark-empty pen + Undo / Hint / Check /
 * Restart, plus the calm progress bar.
 *
 * Replaces the legacy HUD chrome under [data-palette]. We keep the existing
 * store actions and bus events intact; nothing about the engine changes.
 *
 * Time complexity: render O(1) — board state is read via narrow selectors so
 * mark changes don't re-render the toolbar itself.
 */
export function SleepyCatToolbar() {
  const primary = useStore((s) => s.primary);
  const canUndo = useStore((s) => s.undoStack.length > 0);
  const cellsLen = useStore((s) => s.board.cells.length);
  const a = useGameActions();
  const [hintNote, setHintNote] = useState(false);

  const onSetFill = useCallback(() => a.setPrimary('fill'), [a]);
  const onSetMark = useCallback(() => a.setPrimary('cross'), [a]);
  const onUndo = useCallback(() => a.undo(), [a]);
  const onCheck = useCallback(() => bus.emit('scCheckRequested', {}), []);
  const onHint = useCallback(() => {
    placeOneHint();
    setHintNote(true);
    setTimeout(() => setHintNote(false), 2200);
  }, []);
  const onRestart = useCallback(() => {
    if (confirm('Start this puzzle over?')) a.restart();
  }, [a]);

  if (cellsLen === 0) return null;

  return (
    <>
      <div className="sc-toolbar" data-testid="sc-toolbar">
        <div className="sc-seg" role="group" aria-label="Pen mode">
          <button
            type="button"
            className="sc-seg-btn"
            aria-pressed={primary === 'fill'}
            aria-label="Fill mode"
            onClick={onSetFill}
            data-testid="sc-pen-fill"
          >
            <span className="sc-seg-ico fill" aria-hidden="true" />
            <span className="sc-btn-label">Fill</span>
          </button>
          <button
            type="button"
            className="sc-seg-btn"
            aria-pressed={primary === 'cross'}
            aria-label="Mark empty mode"
            onClick={onSetMark}
            data-testid="sc-pen-mark"
          >
            <span className="sc-seg-ico mark" aria-hidden="true">✕</span>
            <span className="sc-btn-label">Mark empty</span>
          </button>
        </div>

        <div className="sc-tool-spacer" />

        <button
          type="button"
          className="sc-tool-btn"
          onClick={onUndo}
          disabled={!canUndo}
          aria-label="Undo last move"
          data-testid="sc-undo"
        >
          <UndoIcon /> <span className="sc-btn-label">Undo</span>
        </button>
        <button
          type="button"
          className="sc-tool-btn"
          onClick={onHint}
          aria-label="Show a hint"
          data-testid="sc-hint"
        >
          <HintIcon /> <span className="sc-btn-label">Hint</span>
        </button>
        <button
          type="button"
          className="sc-tool-btn"
          onClick={onCheck}
          aria-label="Check for mistakes"
          data-testid="sc-check"
        >
          <CheckIcon /> <span className="sc-btn-label">Check</span>
        </button>
        <button
          type="button"
          className="sc-tool-btn"
          onClick={onRestart}
          aria-label="Start over"
          data-testid="sc-restart"
        >
          <RestartIcon /> <span className="sc-btn-label">Restart</span>
        </button>
      </div>

      <SleepyCatProgress />

      {hintNote && (
        <div className="sc-footnote" data-testid="sc-hint-note" role="status" aria-live="polite">
          A hint has been placed for you.
        </div>
      )}
    </>
  );
}

/**
 * Calm progress bar — no timer, no time pressure. Fills as the player places
 * correct cells. Subscribes narrowly so it doesn't re-render the toolbar.
 */
function SleepyCatProgress() {
  // Subscribe to the cells array directly so the bar updates as marks change.
  const solved = useStore((s) => s.solved);
  // Pull a small derived progress number; rendering the percent string is cheap.
  const progress = useStore((s) => computeProgress(s.board.solution, s.board.cells));
  const label = solved || progress >= 100 ? 'You did it!' : `${progress}% done`;

  return (
    <div className="sc-progress-wrap" data-testid="sc-progress">
      <div className="sc-progress-track" role="progressbar"
           aria-valuenow={progress} aria-valuemin={0} aria-valuemax={100}
           aria-label="Puzzle progress">
        <div className="sc-progress-fill" style={{ width: `${progress}%` }} />
      </div>
      <div className="sc-progress-label">{label}</div>
    </div>
  );
}

function computeProgress(
  solution: ReadonlyArray<0|1>,
  cells: ReadonlyArray<string>,
): number {
  let target = 0;
  let correct = 0;
  for (let i = 0; i < solution.length; i++) {
    if (solution[i] === 1) {
      target++;
      if (cells[i] === 'fill') correct++;
    }
  }
  if (target === 0) return 0;
  return Math.round((correct / target) * 100);
}

/**
 * Gentle Check — listens to a bus event from the toolbar, finds wrong fills,
 * paints them with a soft red dashed border for 1.5s, then auto-clears.
 *
 * "Wrong" means: cell is filled but solution says empty. We do NOT highlight
 * "missing" fills — that would punish the player for not being done yet.
 */
export function GentleCheck() {
  const board = useGameState().board;
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    function check() {
      const wrong: number[] = [];
      for (let i = 0; i < board.cells.length; i++) {
        if (board.cells[i] === 'fill' && board.solution[i] === 0) {
          wrong.push(i);
        }
      }
      // Clear any previous marks
      document.querySelectorAll('[data-sc-wrong]').forEach((el) => el.removeAttribute('data-sc-wrong'));
      for (const idx of wrong) {
        const el = document.querySelector(`[data-cell-idx="${idx}"]`);
        if (el) el.setAttribute('data-sc-wrong', '');
      }
      if (timerRef.current) clearTimeout(timerRef.current);
      timerRef.current = setTimeout(() => {
        document.querySelectorAll('[data-sc-wrong]').forEach((el) => el.removeAttribute('data-sc-wrong'));
      }, 1500);
    }
    const off = bus.on('scCheckRequested', check);
    return () => {
      if (timerRef.current) clearTimeout(timerRef.current);
      off();
    };
  }, [board]);

  return null;
}

/**
 * Hint pulse — when the hint engine places a cell (via bus 'cellMarked'
 * from a hint, OR when the hint level reaches 3 with a target cell), pulse
 * the affected cell with a gentle ring.
 */
export function HintPulse() {
  useEffect(() => {
    const off = bus.on('hintApplied', ({ row, col, cols }) => {
      const idx = row * cols + col;
      const el = document.querySelector(`[data-cell-idx="${idx}"]`);
      if (!el) return;
      el.setAttribute('data-sc-hint-pulse', '');
      setTimeout(() => el.removeAttribute('data-sc-hint-pulse'), 1200);
    });
    return () => off();
  }, []);
  return null;
}

